'use client';

import { useCallback, useEffect, useMemo, useState } from 'react';
import { useRouter } from 'next/navigation';
import { ApiResponse } from '@/types/api';
import { Product, Variant } from '@/types/product';
import {
  createCurrencyInputState,
  handleCurrencyInputChangeWithState,
} from '@/lib/numeric-input';
import {
  AlertCircle,
  ArrowDownToLine,
  Calculator,
  DollarSign,
  Loader2,
  Receipt,
  TrendingUp,
} from 'lucide-react';
import { Input, InputGroup } from '@tote-bag/ui';
import { apiFetch } from '@/utils/api';
import { useDashboardAuth } from '@/components/dashboard/DashboardAuthContext';

type GatewayMarginGrid = {
  current: {
    ingresoBruto: number;
    ventaNetaSinIva: number;
    iva: number;
    costoProducto: number;
    comisionWompi: number;
    ivaComision: number;
    costoLogisticoCif: number;
    netoRecibidoBanco: number;
    retencionesActivas: number;
    utilidadBruta: number;
    utilidadOperativa: number;
    utilidadNeta: number;
    margenSobreNetoPasarela: number | null;
    alertaMargenBajo: boolean;
  };
  targets: Array<{
    targetMargin: number;
    requiredGrossAmount: number | null;
    requiredNetReceivedAmount: number | null;
    expectedNetProfit: number | null;
    reachable: boolean;
  }>;
};

function formatCurrency(amount: number | null | undefined) {
  if (amount === null || amount === undefined) {
    return '--';
  }

  return new Intl.NumberFormat('es-CO', {
    style: 'currency',
    currency: 'COP',
    maximumFractionDigits: 0,
  }).format(amount);
}

function formatPercentage(value: number | null | undefined) {
  if (value === null || value === undefined) {
    return '--';
  }

  return `${(value * 100).toFixed(1)}%`;
}

function getActiveVariants(product: Product | undefined) {
  if (!product) {
    return [];
  }

  return product.variants.filter((variant) => variant.isActive !== false);
}

function formatVariantLabel(variant: Variant) {
  const parts = [variant.sku, variant.size, variant.color].filter(
    (value): value is string => typeof value === 'string' && value.trim().length > 0,
  );

  return parts.length > 0 ? parts.join(' / ') : 'Variante sin etiqueta';
}

function unwrapApiData<T>(body: ApiResponse<T> | T): T {
  if (body && typeof body === 'object' && 'data' in body) {
    return ((body as ApiResponse<T>).data || null) as T;
  }

  return body as T;
}

export default function ProfitCalculator() {
  const { accessToken } = useDashboardAuth();
  const router = useRouter();
  const [products, setProducts] = useState<Product[]>([]);
  const [selectedProductId, setSelectedProductId] = useState<string>('');
  const [selectedVariantId, setSelectedVariantId] = useState<string>('');
  const [targetMarginPercent, setTargetMarginPercent] = useState('60');
  const [suggestedPrice, setSuggestedPrice] = useState(() =>
    createCurrencyInputState(0),
  );
  const [avgCost, setAvgCost] = useState(() => createCurrencyInputState(''));
  const [productsLoading, setProductsLoading] = useState(true);
  const [productsError, setProductsError] = useState<string | null>(null);
  const [grid, setGrid] = useState<GatewayMarginGrid | null>(null);
  const [gridLoading, setGridLoading] = useState(false);
  const [gridError, setGridError] = useState<string | null>(null);

  const selectedProduct = products.find((item) => item.id === selectedProductId);
  const activeVariants = useMemo(
    () => getActiveVariants(selectedProduct),
    [selectedProduct],
  );
  const selectedVariant =
    activeVariants.find((variant) => variant.id === selectedVariantId) ??
    (activeVariants.length === 1 ? activeVariants[0] : undefined);
  const requiresVariantSelection = activeVariants.length > 1;
  const hasVariantContext = !requiresVariantSelection || Boolean(selectedVariant);
  const referenceTaxRate =
    typeof selectedVariant?.taxRate === 'string'
      ? Number(selectedVariant.taxRate)
      : (selectedVariant?.taxRate ?? 0.19);
  const parsedTargetMarginPercent = Number(
    String(targetMarginPercent).replace(',', '.'),
  );
  const hasValidTargetMargin =
    Number.isFinite(parsedTargetMarginPercent) &&
    parsedTargetMarginPercent >= 0 &&
    parsedTargetMarginPercent <= 100;
  const hasSelection = Boolean(selectedProductId);
  const hasRealCost = avgCost.numericValue > 0;
  const canCalculateMetrics =
    hasSelection &&
    hasVariantContext &&
    hasRealCost &&
    suggestedPrice.numericValue > 0 &&
    hasValidTargetMargin;

  const resolveApiErrorMessage = useCallback(
    async (
      response: Response,
      fallbackMessage: string,
      options?: { redirectOnUnauthorized?: boolean; forbiddenMessage?: string },
    ) => {
      if (response.status === 401) {
        if (options?.redirectOnUnauthorized) {
          router.push(
            `/login?redirect=${encodeURIComponent(window.location.pathname)}`,
          );
        }

        return 'Tu sesion expiro. Inicia sesion nuevamente.';
      }

      if (response.status === 403) {
        return (
          options?.forbiddenMessage ||
          'No tienes permisos para usar este simulador financiero.'
        );
      }

      const body = await response.json().catch(() => null);

      if (typeof body?.message === 'string' && body.message.trim()) {
        return body.message;
      }

      if (Array.isArray(body?.message)) {
        const firstMessage = body.message.find(
          (value: unknown) => typeof value === 'string' && value.trim(),
        );

        if (firstMessage) {
          return firstMessage;
        }
      }

      if (typeof body?.error === 'string' && body.error.trim()) {
        return body.error;
      }

      return fallbackMessage;
    },
    [router],
  );

  useEffect(() => {
    const fetchProducts = async () => {
      try {
        setProductsError(null);

        if (!accessToken) {
          throw new Error('Tu sesion expiro. Inicia sesion nuevamente.');
        }

        const response = await apiFetch('/catalog/admin/products', {
          headers: {
            Authorization: `Bearer ${accessToken}`,
          },
        });

        if (!response.ok) {
          throw new Error(
            await resolveApiErrorMessage(
              response,
              'No se pudo cargar el catalogo de productos.',
              {
                redirectOnUnauthorized: true,
                forbiddenMessage:
                  'No tienes permisos para consultar productos en este simulador.',
              },
            ),
          );
        }

        const body: ApiResponse<Product[]> = await response.json();
        setProducts(body.data || []);
      } catch (error) {
        console.error('Error fetching products:', error);
        setProductsError(
          error instanceof Error
            ? error.message
            : 'No se pudieron cargar los productos para analizar margenes.',
        );
      } finally {
        setProductsLoading(false);
      }
    };

    void fetchProducts();
  }, [accessToken, resolveApiErrorMessage]);

  useEffect(() => {
    if (!selectedProduct) {
      setSelectedVariantId('');
      setAvgCost(createCurrencyInputState(''));
      setSuggestedPrice(createCurrencyInputState(0));
      setGrid(null);
      return;
    }

    const nextVariants = getActiveVariants(selectedProduct);
    if (nextVariants.length === 1) {
      setSelectedVariantId(nextVariants[0].id ?? '');
      return;
    }

    setSelectedVariantId('');
  }, [selectedProduct]);

  useEffect(() => {
    if (!selectedProduct) {
      return;
    }

    if (requiresVariantSelection && !selectedVariant) {
      setAvgCost(createCurrencyInputState(''));
      setSuggestedPrice(createCurrencyInputState(''));
      setGrid(null);
      setGridError(null);
      return;
    }

    setSuggestedPrice(
      createCurrencyInputState(
        selectedVariant?.salePrice ?? selectedProduct.basePrice ?? 0,
      ),
    );
    setAvgCost(
      createCurrencyInputState(
        selectedVariant?.totalCost ?? selectedVariant?.costPrice ?? '',
      ),
    );
    setGrid(null);
    setGridError(null);
  }, [requiresVariantSelection, selectedProduct, selectedVariant]);

  useEffect(() => {
    let active = true;

    const fetchGrid = async () => {
      if (!canCalculateMetrics || !accessToken) {
        setGrid(null);
        setGridError(null);
        setGridLoading(false);
        return;
      }

      setGridLoading(true);
      setGridError(null);

      try {
        const response = await apiFetch('/finance/gateway-margin-grid', {
          method: 'POST',
          headers: {
            Authorization: `Bearer ${accessToken}`,
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({
            grossAmount: suggestedPrice.numericValue,
            productCost: avgCost.numericValue,
            taxRate: referenceTaxRate,
            marginTarget: parsedTargetMarginPercent,
            targetMargins: [parsedTargetMarginPercent],
          }),
        });

        if (!response.ok) {
          throw new Error(
            await resolveApiErrorMessage(
              response,
              'No se pudo calcular la malla financiera.',
              {
                redirectOnUnauthorized: true,
                forbiddenMessage:
                  'No tienes permisos para usar el simulador financiero.',
              },
            ),
          );
        }

        const body = (await response.json()) as ApiResponse<GatewayMarginGrid>;
        if (!active) {
          return;
        }

        setGrid(unwrapApiData(body));
      } catch (error) {
        console.error('Error fetching gateway margin grid:', error);
        if (active) {
          setGridError(
            error instanceof Error
              ? error.message
              : 'No se pudo calcular la malla financiera.',
          );
          setGrid(null);
        }
      } finally {
        if (active) {
          setGridLoading(false);
        }
      }
    };

    void fetchGrid();

    return () => {
      active = false;
    };
  }, [
    accessToken,
    avgCost.numericValue,
    canCalculateMetrics,
    parsedTargetMarginPercent,
    referenceTaxRate,
    resolveApiErrorMessage,
    suggestedPrice.numericValue,
  ]);

  const current = grid?.current ?? null;

  return (
    <div className="rounded-2xl border border-theme bg-surface p-6 shadow-sm">
      <div className="mb-6 flex items-center gap-3">
        <div className="rounded-lg bg-primary/10 p-2">
          <Calculator className="h-5 w-5 text-primary" />
        </div>
        <div>
          <h2 className="text-xl font-bold text-primary">
            Malla de Margen sobre Neto de Pasarela
          </h2>
          <p className="text-xs font-medium text-muted">
            Calcula con backend financiero, no solo sobre PVP con IVA.
          </p>
        </div>
      </div>

      <div className="grid grid-cols-1 gap-8 xl:grid-cols-[1.05fr_1fr]">
        <div className="space-y-6">
          <div>
            <label className="mb-2 block text-sm font-bold uppercase tracking-wider text-muted">
              Seleccionar Producto
            </label>
            {productsLoading ? (
              <div className="flex items-center gap-2 py-2 text-muted">
                <Loader2 className="h-4 w-4 animate-spin" />
                <span>Cargando productos...</span>
              </div>
            ) : productsError ? (
              <div className="rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">
                {productsError}
              </div>
            ) : (
              <select
                value={selectedProductId}
                onChange={(event) => setSelectedProductId(event.target.value)}
                className="w-full rounded-xl border border-theme bg-base px-4 py-3 font-medium text-primary outline-none transition-all focus:ring-2 focus:ring-primary/20"
              >
                <option value="">Seleccione un producto</option>
                {products.map((product) => (
                  <option key={product.id} value={product.id}>
                    {product.name}
                  </option>
                ))}
              </select>
            )}
          </div>

          {hasSelection && requiresVariantSelection ? (
            <div>
              <label className="mb-2 block text-sm font-bold uppercase tracking-wider text-muted">
                Seleccionar Variante
              </label>
              <select
                value={selectedVariantId}
                onChange={(event) => setSelectedVariantId(event.target.value)}
                className="w-full rounded-xl border border-theme bg-base px-4 py-3 font-medium text-primary outline-none transition-all focus:ring-2 focus:ring-primary/20"
              >
                <option value="">Seleccione una variante comercial</option>
                {activeVariants.map((variant) => (
                  <option key={variant.id} value={variant.id}>
                    {formatVariantLabel(variant)}
                  </option>
                ))}
              </select>
              <p className="mt-1 text-[10px] font-medium italic text-muted">
                Este producto tiene variantes con precio o costo comercial
                propio. Debes elegir una para simular.
              </p>
            </div>
          ) : null}

          <div>
            <label className="mb-2 block text-sm font-bold uppercase tracking-wider text-muted">
              Costo del Producto
            </label>
            <InputGroup
              prefix={<span className="font-bold text-muted">$</span>}
              className="flex items-center gap-2 rounded-xl border border-theme bg-base px-4"
            >
              <Input
                type="text"
                inputMode="decimal"
                value={avgCost.formattedValue}
                disabled={!hasSelection || !hasVariantContext}
                onChange={(event) =>
                  handleCurrencyInputChangeWithState(event, setAvgCost)
                }
                className="w-full bg-transparent py-3 font-bold text-primary outline-none transition-all focus:ring-0 disabled:cursor-not-allowed disabled:opacity-60"
              />
            </InputGroup>
            <p className="mt-1 text-[10px] font-medium italic text-muted">
              Usa costo real o ajusta manualmente para simular escenarios.
            </p>
          </div>

          <div>
            <label className="mb-2 block text-sm font-bold uppercase tracking-wider text-muted">
              Porcentaje de Ganancia
            </label>
            <InputGroup
              suffix={<span className="font-bold text-muted">%</span>}
              className="flex items-center gap-2 rounded-xl border border-theme bg-base px-4"
            >
              <Input
                type="number"
                inputMode="decimal"
                min={0}
                max={100}
                step="0.1"
                value={targetMarginPercent}
                disabled={!hasSelection || !hasVariantContext}
                onChange={(event) => setTargetMarginPercent(event.target.value)}
                className="w-full bg-transparent py-3 font-bold text-primary outline-none transition-all focus:ring-0 disabled:cursor-not-allowed disabled:opacity-60"
              />
            </InputGroup>
            <p className="mt-1 text-[10px] font-medium italic text-muted">
              Meta de utilidad sobre neto de pasarela para esta simulacion.
            </p>
            {!hasValidTargetMargin && hasSelection ? (
              <p className="mt-1 text-[10px] font-medium text-red-700">
                Ingresa un porcentaje valido entre 0 y 100.
              </p>
            ) : null}
          </div>

          <div>
            <label className="mb-2 block text-sm font-bold uppercase tracking-wider text-muted">
              PVP con IVA
            </label>
            <InputGroup
              prefix={<span className="font-bold text-muted">$</span>}
              className="flex items-center gap-2 rounded-xl border border-theme bg-base px-4"
            >
              <Input
                type="text"
                inputMode="decimal"
                value={suggestedPrice.formattedValue}
                disabled={!hasSelection || !hasVariantContext}
                onChange={(event) =>
                  handleCurrencyInputChangeWithState(event, setSuggestedPrice)
                }
                className="w-full bg-transparent py-3 font-bold text-primary outline-none transition-all focus:ring-0 disabled:cursor-not-allowed disabled:opacity-60"
              />
            </InputGroup>
            <p className="mt-1 text-[10px] font-medium italic text-muted">
              Tarifa IVA de referencia: {(referenceTaxRate * 100).toFixed(0)}%.
            </p>
          </div>

          <div className="grid grid-cols-1 gap-3">
            {(grid?.targets || []).map((target) => (
              <div
                key={target.targetMargin}
                className="rounded-xl border border-theme bg-base px-4 py-4"
              >
                <p className="text-[10px] font-bold uppercase tracking-widest text-muted">
                  Meta {formatPercentage(target.targetMargin)}
                </p>
                <p className="mt-2 text-lg font-black text-primary">
                  {target.reachable
                    ? formatCurrency(target.requiredGrossAmount)
                    : 'No alcanzable'}
                </p>
                <p className="mt-1 text-[11px] font-medium text-muted">
                  Neto estimado:{' '}
                  {target.reachable
                    ? formatCurrency(target.requiredNetReceivedAmount)
                    : '--'}
                </p>
              </div>
            ))}
          </div>
        </div>

        <div className="space-y-6 rounded-2xl border border-primary/10 bg-primary/5 p-6">
          {!hasSelection ? (
            <div className="flex items-start gap-3 rounded-xl border border-theme bg-base px-4 py-3 text-sm text-muted">
              <AlertCircle className="mt-0.5 h-4 w-4 shrink-0" />
              <p>
                Selecciona un producto para calcular utilidad real y margen
                sobre recaudo neto de pasarela.
              </p>
            </div>
          ) : null}

          {hasSelection && requiresVariantSelection && !selectedVariant ? (
            <div className="flex items-start gap-3 rounded-xl border border-amber-200 bg-amber-50 px-4 py-3 text-sm text-amber-800">
              <AlertCircle className="mt-0.5 h-4 w-4 shrink-0" />
              <p>
                Selecciona una variante comercial antes de calcular. Este
                producto no tiene una referencia unica de costo, IVA y PVP.
              </p>
            </div>
          ) : null}

          {gridLoading ? (
            <div className="flex items-center gap-2 rounded-xl border border-theme bg-base px-4 py-3 text-sm font-medium text-muted">
              <Loader2 className="h-4 w-4 animate-spin" />
              Calculando motor financiero...
            </div>
          ) : null}

          {gridError ? (
            <div className="rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm font-medium text-red-700">
              {gridError}
            </div>
          ) : null}

          <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
            <div className="rounded-xl border border-theme bg-base px-4 py-4">
              <p className="text-[10px] font-bold uppercase tracking-widest text-muted">
                Venta neta sin IVA
              </p>
              <p className="mt-2 text-2xl font-black text-primary">
                {formatCurrency(current?.ventaNetaSinIva)}
              </p>
            </div>
            <div className="rounded-xl border border-theme bg-base px-4 py-4">
              <p className="text-[10px] font-bold uppercase tracking-widest text-muted">
                Neto recibido banco
              </p>
              <p className="mt-2 flex items-center gap-2 text-2xl font-black text-blue-600">
                <ArrowDownToLine className="h-5 w-5" />
                {formatCurrency(current?.netoRecibidoBanco)}
              </p>
            </div>
            <div className="rounded-xl border border-theme bg-base px-4 py-4">
              <p className="text-[10px] font-bold uppercase tracking-widest text-muted">
                Utilidad bruta
              </p>
              <p className="mt-2 flex items-center gap-2 text-2xl font-black text-primary">
                <DollarSign className="h-5 w-5" />
                {formatCurrency(current?.utilidadBruta)}
              </p>
            </div>
            <div className="rounded-xl border border-theme bg-base px-4 py-4">
              <p className="text-[10px] font-bold uppercase tracking-widest text-muted">
                Utilidad neta real
              </p>
              <p className="mt-2 text-2xl font-black text-emerald-600">
                {formatCurrency(current?.utilidadNeta)}
              </p>
            </div>
          </div>

          <div className="grid grid-cols-1 gap-3 md:grid-cols-3">
            <div className="rounded-xl border border-theme bg-base px-4 py-3">
              <p className="text-[10px] font-bold uppercase tracking-widest text-muted">
                IVA venta
              </p>
              <p className="mt-1 text-lg font-black text-primary">
                {formatCurrency(current?.iva)}
              </p>
            </div>
            <div className="rounded-xl border border-theme bg-base px-4 py-3">
              <p className="text-[10px] font-bold uppercase tracking-widest text-muted">
                Comision + IVA
              </p>
              <p className="mt-1 text-lg font-black text-primary">
                {formatCurrency(
                  (current?.comisionWompi || 0) + (current?.ivaComision || 0),
                )}
              </p>
            </div>
            <div className="rounded-xl border border-theme bg-base px-4 py-3">
              <p className="text-[10px] font-bold uppercase tracking-widest text-muted">
                Retenciones activas
              </p>
              <p className="mt-1 flex items-center gap-2 text-lg font-black text-amber-600">
                <Receipt className="h-4 w-4" />
                {formatCurrency(current?.retencionesActivas)}
              </p>
            </div>
          </div>

          <div className="border-t border-primary/10 pt-4">
            {current ? (
              <div
                className={`rounded-lg px-3 py-3 text-center text-xs font-bold ${
                  current.alertaMargenBajo
                    ? 'bg-rose-100 text-rose-700'
                    : 'bg-emerald-100 text-emerald-700'
                }`}
              >
                {current.alertaMargenBajo
                  ? `ALERTA: margen sobre neto de pasarela en ${formatPercentage(
                      current.margenSobreNetoPasarela,
                    )}, por debajo del objetivo de ${parsedTargetMarginPercent.toFixed(1)}%`
                  : `Margen sobre neto de pasarela saludable: ${formatPercentage(
                      current.margenSobreNetoPasarela,
                    )}`}
              </div>
            ) : (
              <div className="rounded-lg bg-zinc-100 px-3 py-2 text-center text-xs font-bold text-zinc-500 dark:bg-zinc-800 dark:text-zinc-400">
                SIN DATOS SUFICIENTES PARA CALCULAR EL MOTOR FINANCIERO
              </div>
            )}
          </div>

          {canCalculateMetrics &&
          suggestedPrice.numericValue < avgCost.numericValue ? (
            <div className="rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm font-medium text-red-700">
              El PVP con IVA esta por debajo del costo cargado para este
              escenario.
            </div>
          ) : null}

          <div className="rounded-xl border border-theme bg-base px-4 py-4">
            <p className="text-[10px] font-bold uppercase tracking-widest text-muted">
              Referencia actual
            </p>
            <p className="mt-2 flex items-center gap-2 text-sm font-bold text-primary">
              <TrendingUp className="h-4 w-4 text-primary" />
              {selectedVariant ? formatVariantLabel(selectedVariant) : 'Sin variante comercial seleccionada'}
            </p>
            <p className="mt-1 text-[11px] font-medium text-muted">
              El backend estima Wompi, IVA comision, CIF empaque y retenciones
              con la configuracion actual del ambiente.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}
